<?php
namespace App\Http\Controllers\Admin\Catalog;
use App\Actions\Catalog\{CreateProduct,UpdateProduct,PublishProduct,UnpublishProduct};
use App\Http\Controllers\Controller; use App\Http\Requests\Admin\Catalog\{StoreProductRequest,UpdateProductRequest}; use App\Models\Product; use Illuminate\Http\RedirectResponse; use Inertia\{Inertia,Response};
class ProductController extends Controller { public function index():Response{$this->authorize('viewAny',Product::class);return Inertia::render('Admin/Products/Index',['products'=>Product::query()->with(['brand','category'])->latest()->paginate()]);} public function create():Response{$this->authorize('create',Product::class);return Inertia::render('Admin/Products/Create');} public function store(StoreProductRequest $request,CreateProduct $action):RedirectResponse{$product=$action->handle($request->validated());return to_route('admin.products.edit',$product)->with('success','Product created.');} public function edit(Product $product):Response{$this->authorize('update',$product);return Inertia::render('Admin/Products/Edit',['product'=>$product->load(['categories','collections','materials','finishes','colors','tags','features','rooms'])]);} public function update(UpdateProductRequest $request,Product $product,UpdateProduct $action):RedirectResponse{$this->authorize('update',$product);$action->handle($product,$request->validated());return back()->with('success','Product updated.');} public function destroy(Product $product):RedirectResponse{$this->authorize('delete',$product);$product->delete();return to_route('admin.products.index')->with('success','Product deleted.');} public function publish(Product $product,PublishProduct $action):RedirectResponse{$this->authorize('update',$product);$action->handle($product);return back()->with('success','Product published.');} public function unpublish(Product $product,UnpublishProduct $action):RedirectResponse{$this->authorize('update',$product);$action->handle($product);return back()->with('success','Product unpublished.');} }
